"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["89195"],{6620(e){e.exports=JSON.parse('{"id":"V4-216","slug":"deepfake-fraud","term":"Deepfake Fraud","also_known_as":[],"difficulty":"Intermediate","definition":"Deepfake fraud is fraud that uses artificial intelligence to create realistic fake videos, images or audio of real people, to deceive victims into transferring money, sharing information or approving transactions.","explanation":["Deepfake technology uses AI to imitate a person\u2019s face, voice or both. As these tools have become more advanced and accessible, criminals have begun using them to impersonate executives, family members, celebrities and customers.","Common types include voice cloning to impersonate a company executive or relative on the phone, requesting urgent payments; fake video calls impersonating senior managers; fake celebrity videos promoting investment scams; and attempts to fool identity verification systems used by banks to open accounts.","For example, in a widely reported case in Hong Kong in 2024, an employee of a multinational company was tricked into transferring about 25 million US dollars after joining a video call in which the company\u2019s finance chief and other colleagues were all deepfakes.","Defences include verifying unusual requests through separate, trusted channels, such as calling back on a known number; using code words for sensitive requests; requiring multiple approvals for large payments; training staff; and deploying detection technology. Financial institutions are strengthening identity verification with liveness checks, which test whether a real person is present."],"note":"","total":1725,"prev":{"slug":"deductible","term":"Deductible"},"next":{"slug":"default","term":"Default"}}')}}]);